package dev.pocketrun.core

import java.io.File
import java.util.Locale

/**
 * What a file is to the UI. The tree icon, the viewer, the filter chip and the
 * "открыть" action all read this one classification, so a file can never open in
 * the wrong viewer because two lists disagreed about its type.
 */
enum class FileKind(val title: String) {
    FOLDER("Папка"),
    CODE("Код"),
    TEXT("Текст"),
    IMAGE("Фото"),
    AUDIO("Аудио"),
    VIDEO("Видео"),
    ARCHIVE("Архив"),
    OTHER("Файл"),
}

/** One row of the tree. A flat list with a depth keeps LazyColumn cheap. */
data class FileNode(
    val file: File,
    val depth: Int,
    val kind: FileKind,
    val size: Long,
    val modified: Long,
    val folders: Int = 0,
    val files: Int = 0,
) {
    val name: String get() = file.name
    val isFolder: Boolean get() = kind == FileKind.FOLDER
}

/** What the tree shows: a name substring, one kind, and whether dotfiles count. */
data class TreeFilter(
    val query: String = "",
    val kind: FileKind? = null,
    val showHidden: Boolean = false,
=== Mime ===
package dev.pocketrun.core

import android.webkit.MimeTypeMap
import java.io.File
import java.util.Locale

/**
 * The content type to hand the system with a file. Android's own lookup table is
 * used first, then a per-kind fallback: a .md or an .log has no registered type
 * and would otherwise open as "nothing", while every viewer out there will take
 * text/plain.
 */
object Mime {

    fun of(file: File): String {
        val ext = FileTree.ext(file)
        MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext)
            ?.takeIf { it.isNotBlank() }
            ?.let { return it }
        return when (FileTree.kindOf(file)) {
            FileKind.IMAGE -> "image/*"
            FileKind.AUDIO -> "audio/*"
            FileKind.VIDEO -> "video/*"
            FileKind.CODE, FileKind.TEXT -> "text/plain"
            FileKind.ARCHIVE -> "application/octet-stream"
            else -> "application/octet-stream"
        }
    }

    fun extensionOf(type: String): String = type.substringAfterLast('/', "bin").lowercase(Locale.ROOT)
}

